        assert anchor.is_cuda and positive.is_cuda and negative.is_cuda
        assert anchor.dtype == torch.float32
        assert anchor.shape == positive.shape == negative.shape

        anchor = anchor.contiguous()
        positive = positive.contiguous()
        negative = negative.contiguous()

        batch_size, dim = anchor.shape

        output = torch.zeros((), device=anchor.device, dtype=torch.float32)

        module = _get_ptx_module()

        module.launch(
            "triplet_margin_loss_kernel",
            grid=(min(batch_size, 256), 1, 1),
            block=(512, 1, 1),
            arguments=[
                anchor,
                positive,
                negative,
                output,
                i32(batch_size),
                i32(dim),
                f32(self.margin),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(anchor.device),
        )

        return output

